insert into public.vehicle_translations (vehicle_id, locale, title, description, remarks) values ('b0000000-0000-4000-8000-000000000001', 'en', '2019 Toyota Land Cruiser Prado TX-L 7-Seater', 'One-owner Prado with full service records, third-row seating and the TX-L leather package. Timing chain engine, locking centre differential and factory navigation. Underbody inspected and rust-free.', 'Spare key included. Minor stone chips on bonnet (see photos).');
insert into public.vehicle_translations (vehicle_id, locale, title, description, remarks) values ('b0000000-0000-4000-8000-000000000001', 'ja', '2019年 トヨタ ランドクルーザープラド TX-L 7人乗り', 'ワンオーナー、整備記録簿付き。TX-Lレザーパッケージ、3列シート、純正ナビ装備。下回り点検済み、錆なし。', 'スペアキー付き。ボンネットに小さな飛び石傷あり。');
insert into public.vehicle_translations (vehicle_id, locale, title, description, remarks) values ('b0000000-0000-4000-8000-000000000001', 'ar', 'تويوتا لاند كروزر برادو TX-L موديل 2019 - 7 مقاعد', 'مالك واحد مع سجل صيانة كامل، صف ثالث من المقاعد وحزمة TX-L الجلدية. قفل الترس التفاضلي الأوسط ونظام ملاحة أصلي. تم فحص الهيكل السفلي وخالٍ من الصدأ.', 'يشمل مفتاحًا احتياطيًا. خدوش صغيرة من الحصى على غطاء المحرك.');
