insert into public.inquiries (id, customer_id, vehicle_id, kind, subject, status, destination_port, is_demo, created_by, created_at, last_message_at) values ('e0000000-0000-4000-8000-000000000001', 'c0000000-0000-4000-8000-000000000001', 'b0000000-0000-4000-8000-000000000002', 'inquiry', 'Hiace Van — CFR Lagos price?', 'new', 'Lagos (Tin Can Island)', true, 'a0000000-0000-4000-8000-000000000011', (now() - interval '9 days'), (now() - interval '9 days'));
insert into public.messages (inquiry_id, customer_id, sender_id, sender_role, body, created_at, read_at) values ('e0000000-0000-4000-8000-000000000001', 'c0000000-0000-4000-8000-000000000001', 'a0000000-0000-4000-8000-000000000011', 'customer', 'Hello, I am interested in this Hiace. Can you give me a CFR price to Lagos (Tin Can)? Is the engine 1GD diesel?', (now() - interval '9 days'), (now() - interval '8.9 days'));
insert into public.messages (inquiry_id, customer_id, sender_id, sender_role, body, created_at, read_at) values ('e0000000-0000-4000-8000-000000000001', 'c0000000-0000-4000-8000-000000000001', 'a0000000-0000-4000-8000-000000000002', 'sales', 'Hi Amara, thank you for your inquiry. Yes, it is the 1GD 2.8 L diesel. I have sent a quotation for CFR Tin Can Island. RoRo departs from Nagoya roughly every 10 days.', (now() - interval '8.8 days'), (now() - interval '8.7 days'));
insert into public.messages (inquiry_id, customer_id, sender_id, sender_role, body, created_at, read_at) values ('e0000000-0000-4000-8000-000000000001', 'c0000000-0000-4000-8000-000000000001', 'a0000000-0000-4000-8000-000000000011', 'customer', 'Thank you. The quotation works for me. Please reserve it while I arrange the deposit.', (now() - interval '7 days'), (now() - interval '6.9 days'));
insert into public.messages (inquiry_id, customer_id, sender_id, sender_role, body, created_at, read_at) values ('e0000000-0000-4000-8000-000000000001', 'c0000000-0000-4000-8000-000000000001', 'a0000000-0000-4000-8000-000000000002', 'sales', 'Reserved for you for 5 days. The proforma invoice will follow in your documents section.', (now() - interval '6.9 days'), (now() - interval '6.8 days'));
insert into public.internal_notes (customer_id, inquiry_id, author_id, body, created_at) values ('c0000000-0000-4000-8000-000000000001', 'e0000000-0000-4000-8000-000000000001', 'a0000000-0000-4000-8000-000000000002', 'Repeat dealer — usually pays deposit within 48h. Offered free fuel-filter set.', (now() - interval '7 days'));
insert into public.inquiries (id, customer_id, vehicle_id, kind, subject, status, destination_port, is_demo, created_by, created_at, last_message_at) values ('e0000000-0000-4000-8000-000000000002', 'c0000000-0000-4000-8000-000000000002', 'b0000000-0000-4000-8000-000000000020', 'offer', 'Offer on Land Cruiser Prado TZ-G', 'new', 'Jebel Ali', true, 'a0000000-0000-4000-8000-000000000012', (now() - interval '27 days'), (now() - interval '27 days'));
insert into public.messages (inquiry_id, customer_id, sender_id, sender_role, body, created_at, read_at) values ('e0000000-0000-4000-8000-000000000002', 'c0000000-0000-4000-8000-000000000002', 'a0000000-0000-4000-8000-000000000012', 'customer', 'السلام عليكم، أرغب بشراء هذه السيارة. عرضي 42,000 دولار FOB.', (now() - interval '27 days'), (now() - interval '26.9 days'));
insert into public.messages (inquiry_id, customer_id, sender_id, sender_role, body, created_at, read_at) values ('e0000000-0000-4000-8000-000000000002', 'c0000000-0000-4000-8000-000000000002', 'a0000000-0000-4000-8000-000000000003', 'sales', 'Wa alaikum assalam Omar, thank you for your offer. The best we can do is USD 43,900 FOB including export inspection. Quotation attached.', (now() - interval '26.5 days'), (now() - interval '26.4 days'));
insert into public.messages (inquiry_id, customer_id, sender_id, sender_role, body, created_at, read_at) values ('e0000000-0000-4000-8000-000000000002', 'c0000000-0000-4000-8000-000000000002', 'a0000000-0000-4000-8000-000000000012', 'customer', 'OK, agreed. Please send the invoice.', (now() - interval '26 days'), (now() - interval '25.9 days'));
insert into public.messages (inquiry_id, customer_id, sender_id, sender_role, body, created_at, read_at) values ('e0000000-0000-4000-8000-000000000002', 'c0000000-0000-4000-8000-000000000002', 'a0000000-0000-4000-8000-000000000003', 'sales', 'Payment received in full, thank you. Your vehicle is booked on the next RoRo to Jebel Ali.', (now() - interval '20 days'), (now() - interval '19.9 days'));
insert into public.messages (inquiry_id, customer_id, sender_id, sender_role, body, created_at, read_at) values ('e0000000-0000-4000-8000-000000000002', 'c0000000-0000-4000-8000-000000000002', 'a0000000-0000-4000-8000-000000000003', 'sales', 'The vessel departed Yokohama. Bill of lading is now in your documents.', (now() - interval '6 days'), (now() - interval '5.9 days'));
