insert into public.messages (inquiry_id, customer_id, sender_id, sender_role, body, created_at, read_at) values ('e0000000-0000-4000-8000-000000000003', 'c0000000-0000-4000-8000-000000000003', 'a0000000-0000-4000-8000-000000000013', 'customer', 'Hi, does this X-Trail meet KEBS age rules for Kenya? Please quote CIF Mombasa.', (now() - interval '85 days'), (now() - interval '84.9 days'));
